cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO quote -- base premiums", () => {
  it.todo("empty item list -- premium 5 G (processing fee only)");
  it.todo("single plain sword -- base 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("single plain amulet -- base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("single plain staff -- base 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("single plain potion -- base 40 G + 4 G first insurance + 5 G fee = 45 G");
  it.todo("single rune -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
  it.todo("single moonstone -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
});

describe("MHPCO quote -- component blocks", () => {
  it.todo("2 runes -- base premium 50 G (no block)");
  it.todo("3 runes -- base premium 60 G (block applies)");
  it.todo("4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("7 runes -- base premium 175 G (no block; block requires exactly 3)");
  it.todo("2 runes + 1 moonstone -- base premium 75 G (no block: different types are not alike)");
  it.todo("3 runes + 3 moonstones -- base premium 120 G (two separate blocks, one per type)");
});

describe("MHPCO quote -- item-specific modifiers", () => {
  it.todo("cursed sword adds 50 % of that item's base premium -- 50 G surcharge");
  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge -- 30 G");
  it.todo("sword with enchantment 4 adds no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 -- both surcharges apply (50 G + 30 G)");
  it.todo("cursed sword + plain amulet -- policy base 160 G, curse adds 50 G (50 % of the cursed item only) = 210 G before policy modifiers and fee");
});

describe("MHPCO quote -- policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years -- 20 % loyalty discount on the policy base premium");
  it.todo("customer with 1 year -- no loyalty discount");
  it.todo("first quote of the scenario -- 10 % first insurance surcharge on the policy base premium");
  it.todo("second quote of the scenario -- 15 % follow-up contract discount applies");
  it.todo("first insurance surcharge still applies to the second quote (each quoted item is a first insurance)");
  it.todo("5 G processing fee is added at the very end, after all percentage modifiers");
});

describe("MHPCO quote -- rounding", () => {
  it.todo("premium of 197.5 G rounds up to 198 G (in the MHPCO's favor)");
  it.todo("intermediate amounts stay fractional; only the final premium is rounded");
});

describe("MHPCO quote -- integration examples", () => {
  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("3-year customer, second quote, cursed steel sword enchantment 7 -- premium 160 G");
});

describe("MHPCO quote -- rejections", () => {
  it.todo("quote with an unknown item type (broomstick) throws an Error (adopted reading: unknown type is rejected; spec defines only non-zero CLI exit and stderr description)");
});

describe("MHPCO claim -- standard reimbursement", () => {
  it.todo("regular steel sword enchantment 3, damage 500 G -- payout 400 G (full minus 100 G deductible)");
  it.todo("rune (no enchantment, no material), damage 200 G -- payout 100 G (full minus 100 G deductible)");
  it.todo("damage below the deductible -- payout 0 G, never negative");
});

describe("MHPCO claim -- special clauses", () => {
  it.todo("steel sword enchantment 9, damage 1000 G -- payout 400 G (50 % first, then deductible)");
  it.todo("steel sword enchantment 8, damage 1000 G -- payout 400 G (threshold is enchantment >= 8)");
  it.todo("steel sword enchantment 7, damage 1000 G -- payout 900 G (no high-enchantment clause)");
  it.todo("dragon-material sword enchantment 5, damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword enchantment 8, damage 1000 G -- payout 400 G (50 % rule wins over dragon material, then deductible)");
  it.todo("dragon-material sword enchantment 9, damage 1000 G -- payout 400 G (both clauses apply; 50 % rule wins)");
});

describe("MHPCO claim -- deductible per damage event", () => {
  it.todo("sword damage 500 G and amulet damage 300 G in one incident -- payout 600 G (100 G deductible per damaged item)");
  it.todo("two sword damage entries on a policy covering two swords -- each entry gets its own deductible");
});

describe("MHPCO claim -- insurance sum and cap", () => {
  it.todo("policy covering a sword and an amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes -- insurance sum 1750 G, cap 3500 G (block discount affects premium only)");
  it.todo("cursed sword with modified premium 165 G -- cap 2000 G (cap is based on the unmodified insurance value)");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G -- payout 1400 G, remainingCap 600 G");
  it.todo("sword policy, second successive claim of 1500 G -- payout 600 G, remainingCap 0 G (reduced to the remaining cap)");
});

describe("MHPCO claim -- rounding", () => {
  it.todo("payout of 350.5 G rounds down to 350 G (in the MHPCO's favor)");
});

describe("MHPCO claim -- rejections", () => {
  it.todo("damage to an item not covered by the policy (amulet damaged, only a sword insured) throws an Error");
  it.todo("damage entry with an unknown item type throws an Error");
  it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) throws an Error");
  it.todo("damage entry with a negative amount (-200) throws an Error");
});

describe("claim-office CLI", () => {
  it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("schema example scenario (5-year customer, amulet quote then 200 G amulet claim) -- premium and payout/remainingCap results");
  it.todo("claim step result contains both payout and remainingCap");
  it.todo("exits non-zero and writes an error description to stderr, with no results on stdout, for an unknown quote item type");
  it.todo("exits non-zero and writes an error description to stderr for a claim damage entry not covered by the policy");
  it.todo("exits non-zero and writes an error description to stderr for a claim damage entry with a negative amount");
  it.todo("exits non-zero and writes an error description to stderr when damage entries of a type exceed the insured count");
});
EOF
pnpm test 2>&1 | tail -12

